// Clean-room explicit-choice profile of randomized vector scheduling.
use core::ptr;const N:usize=16;const M:usize=8;const D:usize=4;const INPUT:usize=83;const FIELDS:usize=35;
fn put(out:*mut u8,at:usize,x:i64){let b=x as u64;for i in 0..8{unsafe{ptr::write(out.add(at+i),(b>>(8*i))as u8);}}}
#[no_mangle]
pub unsafe extern "C" fn vector_scheduling(input:*const i64,length:usize,output:*mut u8,capacity:usize)->i64{if input.is_null()||length<3||length>INPUT{return -1;}let n64=*input;let m64=*input.add(1);let d64=*input.add(2);if n64<1||n64>16||m64<1||m64>8||d64<1||d64>4||length!=3+n64 as usize+(n64*d64)as usize{return -1;}let n=n64 as usize;let m=m64 as usize;let d=d64 as usize;for j in 0..n{let choice=*input.add(3+j);if choice<0||choice>=m64{return -1;}}for i in 0..n*d{let x=*input.add(3+n+i);if x<0||x>1000{return -1;}}let mut load=[[0i64;D];M];for j in 0..n{let machine=*input.add(3+j)as usize;for q in 0..d{load[machine][q]+=*input.add(3+n+j*d+q);}}let mut span=0i64;for i in 0..m{for q in 0..d{span=span.max(load[i][q]);}}let mut staged=[0i64;FIELDS];let mut count=0;staged[count]=m64;count+=1;staged[count]=d64;count+=1;staged[count]=span;count+=1;for i in 0..m{for q in 0..d{staged[count]=load[i][q];count+=1;}}if output.is_null()||capacity<8*count{return -2;}for i in 0..count{put(output,8*i,staged[i]);} (8*count)as i64}
